with base as (select id, customer_id, start_date, end_date, monthly_fee, floor(monthly_fee) as monthly_fee_whole, date_sub(end_date, 16) as end_date_minus_16d from subscriptions where start_date >= date '2023-09-22' and customer_id is not null) select id, customer_id, end_date, monthly_fee_whole, max(monthly_fee_whole) over (partition by customer_id order by start_date, id rows between unbounded preceding and current row) as running_max_monthly_fee_whole, sum(monthly_fee_whole) over (partition by customer_id order by start_date, id rows between unbounded preceding and current row) as running_sum_monthly_fee_whole, avg(monthly_fee_whole) over (partition by customer_id order by start_date, id rows between unbounded preceding and current row) as running_avg_monthly_fee_whole, min(monthly_fee_whole) over (partition by customer_id order by start_date, id rows between unbounded preceding and current row) as running_min_monthly_fee_whole from base;
